~TSectionMgr();		// frees this object	virtual void DoAESectionEvent(CommandNumber		aCommandNumber,								  const AppleEvent&	message,								  const AppleEvent&	reply);		// responds to the edition manager apple eventspublic:	TSectionList fSectionList;};//----------------------------------------------------------------------------------------// TSectionCommand: an abstract superclass used as the base class for the edition manager// apple event command classes//----------------------------------------------------------------------------------------class EXPORT_MA TSectionCommand : public TServerCommand// TSectionCommand is an abstract class that handles Edition Manager// commands received as an Apple event. TSectionCommand methods// allow you to initialize a command object from an Apple event// and to retrieve a section in the application's document that// corresponds to the section handle.//    TSectionCommand provides subclasses to handle the following// Apple events: Section Read, Section Write, Section Cancel, and// Section Scroll. You can create a subclass for each Apple event// that you want to handle. Your subclass typically provides an// initialization method and a DoIt method. It may also provide// UndoIt, RedoIt, and Commit methods.{public:	TSectionCommand(CommandNumber	itsCommandNumber = NULL,					TDocument*		itsDocument = NULL,					TSection*		itsSection = NULL);		// constructor	TSectionCommand(CommandNumber		itsCommandNumber,					const AppleEvent&	itsMessage,					const AppleEvent&	itsReply);		// constructor	virtual ~TSectionCommand();		// Destructorpublic:	TSection* fSection;							// section object for this apple event command};//----------------------------------------------------------------------------------------// TSectionReadEventCommand//----------------------------------------------------------------------------------------class EXPORT_MA TSectionReadEventCommand : public TSectionCommand// A TSectionReadEventCommand object encapsulates an Apple event// 'read' message in a MacApp command object. The TSectionReadEventCommand// class defines a method to initialize the command object and a// DoIt method to execute the command.//    MacApp creates a TSectionReadEventCommand object when a subscriber// needs to be updated. You seldom need to call or override the// methods of this class. See TCommand for current information about// command objects.{public:	TSectionReadEventCommand(CommandNumber	itsCommandNumber = cNoCommand,							 TDocument*		itsDocument = NULL,							 TSubscriber*	itsSubscriber = NULL);	TSectionReadEventCommand(CommandNumber		itsCommandNumber,							 const AppleEvent&	itsMessage,							 const AppleEvent&	itsReply)		:	TSectionCommand(itsCommandNumber, itsMessage, itsReply) { }		// constructor	virtual ~TSectionReadEventCommand();		// Destructor	virtual void DoIt();		// call ((TSubscriber)fSection)->Subscribe};//----------------------------------------------------------------------------------------// TSectionWriteEventCommand//----------------------------------------------------------------------------------------class EXPORT_MA TSectionWriteEventCommand : public TSectionCommand// A TSectionWriteEventCommand object encapsulates an Apple event// 'writ' message in a MacApp command object. The TSectionWriteEventCommand// class defines a method to initialize the command object and a// DoIt method to execute the command.//    MacApp creates a TSectionWriteEventCommand object when a publisher// publishes a section. You seldom need to call or override the// methods of this class. See TCommand for current information about// command objects.{public:	TSectionWriteEventCommand(CommandNumber		itsCommandNumber = cNoCommand,							  TDocument*		itsDocument = NULL,							  TPublisher*		itsPublisher = NULL)		:	TSectionCommand(itsCommandNumber, itsDocument, itsPublisher) { }	TSectionWriteEventCommand(CommandNumber		itsCommandNumber,							  const AppleEvent&	itsMessage,							  const AppleEvent&	itsReply)		:	TSectionCommand(itsCommandNumber, itsMessage, itsReply) { }		// constructor	virtual ~TSectionWriteEventCommand();		// Destructor	virtual void DoIt();		// call ((TPublisher)fSection))->Publish};//----------------------------------------------------------------------------------------// TSectionScrollEventCommand//----------------------------------------------------------------------------------------class EXPORT_MA TSectionScrollEventCommand : public TSectionCommand// A TSectionScrollEventCommand object encapsulates an Apple event// 'scrl' message in a MacApp command object. The TSectionScrollEventCommand// class defines a method to initialize the command object and a// DoIt method to execute the command.//    MacApp creates a TSectionScrollEventCommand object when it// scrolls a document to reveal the current selection and select// it. You seldom need to call or override the methods of this class.// See TCommand for current information about command objects.{public:	TSectionScrollEventCommand(CommandNumber	itsCommandNumber = cNoCommand,							   TDocument*		itsDocument = NULL,							   TSection*		itsSection = NULL)		:	TSectionCommand(itsCommandNumber, itsDocument, itsSection) { }	TSectionScrollEventCommand(CommandNumber		itsCommandNumber,							   const AppleEvent&	itsMessage,							   const AppleEvent&	itsReply)		:	TSectionCommand(itsCommandNumber, itsMessage, itsReply) { }		// constructor	virtual ~TSectionScrollEventCommand();		// Destructor	virtual void DoIt();		// scrolls the document to the publisher};//----------------------------------------------------------------------------------------// TSectionCancelEventCommand//----------------------------------------------------------------------------------------class EXPORT_MA TSectionCancelEventCommand : public TSectionCommand// A TSectionCancelEventCommand object encapsulates an Apple event// 'cncl' message in a MacApp command object. The TSectionCancelEventCommand// class defines a method to initialize the command object, as well// as DoIt, UndoIt, and Commit methods to execute the command.//    MacApp creates a TSectionCancelEventCommand object when it// responds to the user's request or to an Apple event message to// cancel a section. You seldom need to call or override the methods// of this class. See TCommand for current information about command// objects.{public:	TSectionCancelEventCommand(CommandNumber	itsCommandNumber = cNoCommand,							   TDocument*		itsDocument = NULL,							   TSection*		itsSection = NULL);	inline TSectionCancelEventCommand(CommandNumber		itsCommandNumber,									  const AppleEvent&	itsMessage,									  const AppleEvent&	itsReply)		:	TSectionCommand(itsCommandNumber, itsMessage, itsReply) { }		// constructor	virtual ~TSectionCancelEventCommand();		// Destructor	virtual void DoIt();		// cancels this section	virtual void UndoIt();		// un-cancels this section};//----------------------------------------------------------------------------------------// Global function declarations//----------------------------------------------------------------------------------------EXPORT_MA  void InitUSectionMgr();	// Initialize the section manager and attach it to the application. Note that the    // application should already have been instantiated and initialized when this    // procedure is called.#endif // __USECTIONMGR__/*	Historical Change Record: 		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/24/96	[1345531] Added #include "USection.h" for noload builds		----- R10 -----		12/19/95	Get rid of TSectionCancelEventCommand::Commit.		----- 3.3 -----		----- 3.3b1 -----		 8/14/95	Add overloaded initializers for TServerCommand.		  7/5/95	Cosmetic.		 3/13/95	Change Free methods to destructors.		 9/14/94	Removed DoAppleCommand. Added DoAESectionEvent.							This was necessary when we removed the							scripting behavior.*/